import type { Model } from "../modeler/model.js";
import type { Var } from "../modeler/variable.js";
import type { Constraint } from "../modeler/constraint.js";
import type { LinExpr } from "../modeler/expression.js";
import type {
  SolverStatus,
  SolverSolution,
  SolverOptions,
  Solver,
  VarType,
} from "../modeler/index.js";

/**
 * Definition of a newly proposed column generated by a pricing subproblem.
 */
export interface ColumnProposal<TColumnMeta = unknown> {
  /** Optional variable name for the column */
  name?: string;
  /** Variable domain type (defaults to "Continuous" during LP relaxation, cast to "Integer" during MIP finalization if requested) */
  type?: VarType;
  /** Variable lower bound (default: 0) */
  lb?: number;
  /** Variable upper bound (default: Infinity) */
  ub?: number;
  /** Objective cost coefficient */
  cost: number;
  /**
   * Constraint coefficients for this column.
   * Can be a record keyed by constraint name, Map of Constraint/name to coefficient,
   * or an array of [constraint, coeff] tuples.
   */
  coefficients:
    | Record<string, number>
    | Map<Constraint | string, number>
    | Array<[Constraint | string, number]>
    | Array<{ constraint: Constraint | string; coeff: number }>;
  /**
   * Optional reduced cost computed by the subproblem.
   * For minimization: negative values improve the master objective.
   * For maximization: positive values improve the master objective.
   */
  reducedCost?: number;
  /** Optional domain-specific metadata attached to this column (e.g. pattern vector) */
  meta?: TColumnMeta;
}

/**
 * Context provided to the pricing subproblem callback on each Column Generation iteration.
 */
export interface PricingContext<TColumnMeta = unknown> {
  /** 1-based iteration index */
  iteration: number;
  /** Constraint shadow prices (duals) from the master LP relaxation, keyed by canonical constraint name */
  duals: Record<string, number>;
  /** Helper to retrieve the dual value (shadow price) of a specific constraint */
  getDual: (constraintOrName: Constraint | string) => number;
  /** Full solution payload of the restricted master LP relaxation */
  masterSolution: SolverSolution;
  /** Numerical tolerance for reduced cost optimality check */
  reducedCostTolerance: number;
  /** Master model instance */
  master: Model;
}

/**
 * Declarative subproblem definition for Column Generation.
 * WaSHI automatically sets the subproblem objective using the master's constraint duals,
 * solves it, computes reduced costs, and injects improving columns into the master.
 */
export interface DeclarativeSubproblem<TColumnMeta = unknown> {
  /** The subproblem model or a factory function returning a subproblem model given the pricing context */
  model: Model | ((context: PricingContext<TColumnMeta>) => Promise<Model> | Model);
  /**
   * Mapping from master constraint name (or Constraint object) to the corresponding subproblem decision variable.
   */
  mapping:
    | Record<string, Var>
    | Map<Constraint | string, Var>;
  /** Objective cost coefficient of the generated column (default: 1) */
  cost?: number;
  /** Variable domain type (defaults to "Continuous" during LP relaxation, cast to "Integer" during MIP finalization if requested) */
  type?: VarType;
  /** Column variable lower bound (default: 0) */
  lb?: number;
  /** Column variable upper bound (default: Infinity) */
  ub?: number;
}

/**
 * Progress event emitted on each Column Generation iteration.
 */
export interface ColumnGenerationIterationInfo<TColumnMeta = unknown> {
  iteration: number;
  relaxationObjective: number | null;
  columnsAdded: number;
  proposedColumns: Array<ColumnProposal<TColumnMeta>>;
}

/**
 * Options for `solveColumnGeneration`
 */
export interface ColumnGenerationOptions<TColumnMeta = unknown> {
  /** Restricted Master Problem (RMP) model containing initial columns and constraints (optional when called via `master.solveColumnGeneration(...)`) */
  master?: Model;
  /**
   * Declarative subproblem definition.
   * Automatically sets the subproblem objective using constraint duals, solves it,
   * evaluates the reduced cost, and injects improving columns into the master.
   */
  subproblem?: DeclarativeSubproblem<TColumnMeta>;
  /**
   * Custom pricing subproblem generator callback.
   * Receives constraint duals (shadow prices) and returns one or more new columns with improving reduced costs,
   * or `null` / `[]` when no improving columns exist (LP relaxation is optimal).
   */
  pricing?: (
    context: PricingContext<TColumnMeta>
  ) =>
    | Promise<
        | ColumnProposal<TColumnMeta>
        | ColumnProposal<TColumnMeta>[]
        | null
        | undefined
      >
    | ColumnProposal<TColumnMeta>
    | ColumnProposal<TColumnMeta>[]
    | null
    | undefined;
  /** Maximum number of column generation iterations (default: 100) */
  maxIterations?: number;
  /**
   * Numerical tolerance to test if reduced cost improves the objective (default: 1e-6).
   * For minimization, column is accepted if `reducedCost < -reducedCostTolerance`.
   * For maximization, column is accepted if `reducedCost > reducedCostTolerance`.
   */
  reducedCostTolerance?: number;
  /**
   * Whether to solve the final Restricted Master Problem as a Mixed-Integer Program (MIP)
   * after column generation terminates (default: true).
   * When true, integer/binary columns generate an exact integer solution.
   */
  finalizeAsMIP?: boolean;
  /** Solver name or instance to use for master problem (defaults to HiGHS) */
  solver?: Solver | string;
  /** Solver options passed to master solves */
  solverOptions?: SolverOptions;
  /** Optional callback invoked on each iteration */
  onIteration?: (info: ColumnGenerationIterationInfo<TColumnMeta>) => void;
}

/**
 * Result returned by `solveColumnGeneration`
 */
export interface ColumnGenerationResult<TColumnMeta = unknown> {
  /** Final solver status ("Optimal", "Feasible", "Infeasible", etc.) */
  status: SolverStatus;
  /** Objective value of the final solution (MIP objective if finalized, otherwise LP relaxation objective) */
  objectiveValue: number | null;
  /** Optimal objective value of the continuous LP relaxation (theoretical dual bound) */
  relaxationObjectiveValue: number | null;
  /** Total number of column generation iterations performed */
  iterations: number;
  /** Total number of columns dynamically generated and injected into the master */
  columnsAdded: number;
  /** All dynamically generated columns and their associated `Var` handles */
  generatedColumns: Array<{
    variable: Var;
    proposal: ColumnProposal<TColumnMeta>;
  }>;
  /** The master model containing all generated columns and the final solution state */
  master: Model;
  /** Primal variable values of the final solution */
  values: Record<string, number>;
}

/**
 * Definition of a Benders cut (optimality cut or feasibility cut) to be added to the master problem.
 */
export interface BendersCut {
  /**
   * Cut classification:
   * - "optimality": Benders optimality cut bounding the master auxiliary objective variable theta
   * - "feasibility": Benders feasibility cut cutting off an infeasible subproblem candidate
   */
  kind: "optimality" | "feasibility";
  /** The linear constraint expression representing the cut */
  constraint: Constraint | LinExpr;
  /** Optional cut constraint name */
  name?: string;
  /** Optional subproblem objective or diagnostic value */
  subproblemObjective?: number;
  /** Optional dual values used to generate the cut */
  dualValues?: Record<string, number>;
}

/**
 * Context provided to the Benders subproblem callback on each iteration.
 */
export interface BendersSubproblemContext {
  /** 1-based iteration index */
  iteration: number;
  /** Primal values of master decision variables from the current master solution */
  masterValues: Record<string, number>;
  /** Helper to look up the primal value of a master variable */
  getMasterValue: (v: Var | string) => number;
  /** Current master objective value */
  masterObjective: number | null;
  /** Current best lower bound */
  lowerBound?: number;
  /** Current best upper bound */
  upperBound?: number;
  /** Master model instance */
  master: Model;
}

/**
 * Progress event emitted on each Benders decomposition iteration.
 */
export interface BendersIterationInfo {
  iteration: number;
  masterObjective: number | null;
  lowerBound?: number;
  upperBound?: number;
  cutsAdded: number;
  proposedCuts: BendersCut[];
}

/**
 * Result returned by a Benders subproblem callback.
 * Can be:
 * - A `Model` (or `{ model: Model, linking?: Array<Constraint | LinExpr> }`) for automatic Benders cut generation,
 * - Or `BendersCut | BendersCut[] | null | undefined` for manual cut definition.
 */
export type BendersSubproblemResult =
  | Model
  | {
      model: Model;
      linking?: Array<Constraint | LinExpr>;
    }
  | BendersCut
  | BendersCut[]
  | null
  | undefined;

/**
 * Options for `solveBenders`
 */
export interface BendersOptions {
  /** Master problem model containing master variables (optional when called via `master.solveBenders(...)`) */
  master?: Model;
  /**
   * Subproblem evaluation callback.
   * Evaluates the subproblem given current master decisions.
   * Can return a `Model` (or `{ model: Model, linking?: Array<Constraint | LinExpr> }`) for automatic Benders cut generation,
   * or manual `BendersCut | BendersCut[] | null | undefined`.
   */
  subproblem: (
    context: BendersSubproblemContext
  ) =>
    | Promise<BendersSubproblemResult>
    | BendersSubproblemResult;
  /**
   * Optional reference to the auxiliary theta variable in the master model.
   * If not provided, WaSHI automatically detects a variable named "theta" / "__benders_theta"
   * or injects an auxiliary continuous theta variable into the master objective.
   */
  theta?: Var | string;
  /** Maximum number of Benders iterations (default: 100) */
  maxIterations?: number;
  /** Relative optimality gap convergence tolerance `|upper - lower| / (|upper| + 1e-10)` (default: 1e-4) */
  gapTolerance?: number;
  /** Solver name or instance to use for master problem */
  solver?: Solver | string;
  /** Solver options passed to master solves */
  solverOptions?: SolverOptions;
  /** Optional callback invoked on each iteration */
  onIteration?: (info: BendersIterationInfo) => void;
}

/**
 * Result returned by `solveBenders`
 */
export interface BendersResult {
  /** Final solver status ("Optimal", "Feasible", "Infeasible", etc.) */
  status: SolverStatus;
  /** Final objective value */
  objectiveValue: number | null;
  /** Best lower bound achieved */
  lowerBound?: number;
  /** Best upper bound achieved */
  upperBound?: number;
  /** Final relative optimality gap */
  gap?: number;
  /** Number of iterations performed */
  iterations: number;
  /** Number of Benders cuts added to the master problem */
  cutsAdded: number;
  /** Master model containing all generated cuts and final solution */
  master: Model;
  /** Final primal values of master decision variables */
  values: Record<string, number>;
}
